mapper.select:
SELECT 'issue' kind,id FROM order_issue_report WHERE rental_order_id=#{orderId}
UNION ALL SELECT 'extension',id FROM order_extension_request WHERE active_order_guard=#{orderId}
  AND extension_status!='pending_payment'
UNION ALL SELECT 'claim',id FROM order_claim WHERE rental_order_id=#{orderId}
  AND claim_status!='draft'
    AND user_response_deadline_at IS NOT NULL
UNION ALL SELECT 'arbitration',id FROM arbitration_case WHERE rental_order_id=#{orderId}
UNION ALL SELECT 'receivable',id FROM order_compensation_receivable WHERE rental_order_id=#{orderId}
ORDER BY kind,id
